<script setup lang="ts">
import { computed, ref, watch, onMounted, onUnmounted } from 'vue'
import { Maximize2, Minimize2, RefreshCw, Pause, Play, ArrowUpRight } from 'lucide-vue-next'
import type { FinanceOverview, FinanceInventoryValueStat, FinanceQualityLossStat, FinanceTrendStat, FinanceGroupStat } from '@/api/mes'
const props=defineProps<{overview:FinanceOverview;inventory:FinanceInventoryValueStat;quality:FinanceQualityLossStat;trend:FinanceTrendStat[];suppliers:FinanceGroupStat[];materials:FinanceGroupStat[];loading:boolean;updatedAt:string;scope:string;message:string;entries:{label:string;path:string}[]}>()
const emit=defineEmits<{refresh:[];all:[];month:[value:string];navigate:[path:string]}>()
const screen=ref<HTMLElement>(),canvas=ref<HTMLCanvasElement>(),fullscreen=ref(false),motion=ref(!window.matchMedia('(prefers-reduced-motion: reduce)').matches),now=ref(''),selected=ref(new Date().toISOString().slice(0,7))
const animated=ref({income:0,purchase:0,maintenance:0,balance:0}),activeMonth=ref('')
const total=computed(()=>Number(props.overview.purchaseExpense)+Number(props.overview.maintenanceExpense))
const structure=computed(()=>{const income=Number(props.overview.salesIncome||0);return [{label:'经营结余',value:Math.max(0,Number(props.overview.grossProfit)),tone:'surplus'},{label:'采购成本',value:Number(props.overview.purchaseExpense||0),tone:'purchase'},{label:'维修成本',value:Number(props.overview.maintenanceExpense||0),tone:'repair'}].map(r=>({...r,percent:income>0?r.value/income*100:0}))})
const share=computed(()=>total.value?Number(props.overview.purchaseExpense)/total.value*100:0)
const metrics=computed(()=>[{label:'销售收入',value:animated.value.income,tone:'sage',hint:'销售业务汇总'},{label:'采购支出',value:animated.value.purchase,tone:'gold',hint:'采购业务汇总'},{label:'维修支出',value:animated.value.maintenance,tone:'clay',hint:'设备维护成本'}])
const money=(v:number)=>'¥'+Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
const max=computed(()=>Math.max(1,...props.trend.flatMap(r=>[Number(r.salesIncome),Number(r.purchaseExpense),Number(r.maintenanceExpense)])))
const x=(i:number)=>80+i*540/Math.max(1,props.trend.length)
const height=(v:number)=>Number(v||0)/max.value*120
const hovered=computed(()=>props.trend.find(r=>r.month===activeMonth.value)||props.trend[props.trend.length-1])
let frame=0,numberFrame=0,timer:ReturnType<typeof setInterval>,observer:ResizeObserver,ctx:CanvasRenderingContext2D|null=null,width=0,canvasHeight=0
let particles:{x:number;y:number;r:number;v:number}[]=[]
watch(()=>props.overview,v=>{cancelAnimationFrame(numberFrame);const from={...animated.value},target={income:Number(v.salesIncome),purchase:Number(v.purchaseExpense),maintenance:Number(v.maintenanceExpense),balance:Number(v.grossProfit)},start=performance.now();function step(t:number){const progress=motion.value?Math.min(1,(t-start)/1100):1,ease=1-Math.pow(1-progress,3);for(const key of Object.keys(target) as (keyof typeof target)[])animated.value[key]=from[key]+(target[key]-from[key])*ease;if(progress<1)numberFrame=requestAnimationFrame(step)}numberFrame=requestAnimationFrame(step)},{deep:true,immediate:true})
function draw(){if(!ctx)return;ctx.clearRect(0,0,width,canvasHeight);if(motion.value&&!document.hidden){for(const p of particles){p.y-=p.v;if(p.y<0)p.y=canvasHeight;p.x+=Math.sin(p.y*.006)*.12;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle='rgba(157,119,69,.25)';ctx.fill()}for(let i=0;i<particles.length;i++)for(let j=i+1;j<particles.length;j++){const a=particles[i],b=particles[j],d=Math.hypot(a.x-b.x,a.y-b.y);if(d<100){ctx.strokeStyle=`rgba(157,119,69,${.09*(1-d/100)})`;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}}frame=requestAnimationFrame(draw)}
async function toggleFull(){try{if(document.fullscreenElement)await document.exitFullscreen();else await screen.value?.requestFullscreen()}catch{emit('refresh')}}
const syncFull=()=>fullscreen.value=document.fullscreenElement===screen.value
onMounted(()=>{ctx=canvas.value!.getContext('2d');observer=new ResizeObserver(()=>{width=screen.value!.clientWidth;canvasHeight=screen.value!.clientHeight;const dpr=Math.min(devicePixelRatio,2);canvas.value!.width=width*dpr;canvas.value!.height=canvasHeight*dpr;ctx?.setTransform(dpr,0,0,dpr,0,0);particles=Array.from({length:Math.min(65,Math.round(width/22))},()=>({x:Math.random()*width,y:Math.random()*canvasHeight,r:.7+Math.random()*1.5,v:.15+Math.random()*.3}))});observer.observe(screen.value!);draw();const tick=()=>now.value=new Date().toLocaleString('zh-CN',{hour12:false});tick();timer=setInterval(tick,1000);document.addEventListener('fullscreenchange',syncFull)})
onUnmounted(()=>{cancelAnimationFrame(frame);cancelAnimationFrame(numberFrame);clearInterval(timer);observer?.disconnect();document.removeEventListener('fullscreenchange',syncFull)})
</script>
<template>
<section ref="screen" class="finance-screen" :class="{still:!motion}" :aria-busy="loading">
<canvas ref="canvas" class="particles" aria-hidden="true"/>
<header class="screen-header"><div class="brand-caption">MOUSE MES <span>制造经营数据中心</span></div><div class="screen-title"><small>FINANCIAL OPERATIONS CENTER</small><h1>财务经营 · 动态驾驶舱</h1><i/></div><div class="screen-clock"><strong>{{now}}</strong><span><i/>业务数据在线 · {{updatedAt||'等待同步'}}</span></div></header>
<div class="screen-controls"><span class="scope-pill">{{scope}}</span><span class="sync-note">30 秒自动同步真实业务</span><div class="control-actions"><input v-model="selected" type="month" aria-label="选择财务月份"/><button :disabled="loading" @click="emit('month',selected)">月度</button><button :disabled="loading" @click="emit('all')">全部业务</button><button :disabled="loading" aria-label="刷新数据" @click="emit('refresh')"><RefreshCw :size="14" :class="{spin:loading}"/></button><button :aria-label="motion?'暂停展示动效':'开启展示动效'" @click="motion=!motion"><Pause v-if="motion" :size="14"/><Play v-else :size="14"/></button><button :aria-label="fullscreen?'退出全屏':'全屏展示'" @click="toggleFull"><Minimize2 v-if="fullscreen" :size="14"/><Maximize2 v-else :size="14"/></button></div></div>
<p v-if="message" class="screen-error" role="alert">{{message}}</p>
<div class="screen-grid">
<aside class="left-column"><section class="screen-panel income-panel"><div class="panel-particles" aria-hidden="true"><i v-for="n in 7" :key="n" :style="{left:(n*13)%100+'%',animationDelay:-n*.7+'s',animationDuration:5+n%3+'s'}"/></div><div class="panel-title"><h2>期间收支总览</h2><small>{{scope}}</small></div><article v-for="(m,i) in metrics" :key="m.label" class="screen-metric" :class="m.tone"><div><span class="metric-index">0{{i+1}}</span><span>{{m.label}}</span><i/></div><strong>{{money(m.value)}}</strong><div class="metric-baseline"><span>{{m.hint}}</span><svg viewBox="0 0 90 22" aria-hidden="true"><path d="M0 19H12L18 12H30L36 17H46L53 5H65L72 12H90"/></svg></div></article></section>
<section class="screen-panel supplier-panel"><div class="panel-particles" aria-hidden="true"><i v-for="n in 7" :key="n" :style="{left:(n*13)%100+'%',animationDelay:-n*.7+'s',animationDuration:5+n%3+'s'}"/></div><div class="panel-title"><h2>供应商采购分布</h2><small>累计</small></div><div v-for="(r,i) in suppliers.slice(0,4)" :key="r.groupKey" class="screen-rank"><div><span><b>{{String(i+1).padStart(2,'0')}}</b>{{r.groupName}}</span><strong>{{money(r.amount)}}</strong></div><div class="rank-track"><i :style="{width:Math.max(1,r.amount/Math.max(1,...suppliers.map(v=>v.amount))*100)+'%'}"/></div></div><p v-if="!suppliers.length" class="empty">暂无采购业务</p></section></aside>
<main class="center-column"><section class="flow-panel"><div class="flow-heading"><span class="earnings-title">经营收益<em>收支结余</em></span><small>{{scope}} · CNY</small></div><strong class="hero-value">{{money(animated.balance)}}</strong><p class="earnings-formula">销售收入 − 采购支出 − 维修支出</p>
<div class="earnings-structure"><div class="structure-title"><strong>收益与成本结构</strong><span>以销售收入为基准</span></div><div class="structure-bar" aria-label="经营结余、采购成本、维修成本占销售收入的比例"><i v-for="r in structure" :key="r.label" :class="r.tone" :style="{flexGrow:r.value}" :title="r.label+' '+r.percent.toFixed(1)+'%'"><b/></i></div><div class="structure-labels"><div v-for="r in structure" :key="r.label" :class="r.tone"><span>{{r.label}}</span><strong>{{r.percent.toFixed(1)}}<small>%</small></strong><em>{{money(r.value)}}</em></div></div><small v-if="overview.grossProfit<0" class="loss-note">本期为亏损：支出超过收入，成本占比可能超过 100%</small><small v-else-if="!overview.salesIncome" class="loss-note">当前无销售收入，暂不计算占比</small></div><div class="flow-stage"><svg class="flow-map" viewBox="0 0 600 245" aria-label="收入、采购和维修与收支差额的关系；粒子仅为展示动效"><defs><linearGradient id="financeFlow"><stop stop-color="#b69a6d" stop-opacity=".15"/><stop offset=".5" stop-color="#ead6ae"/><stop offset="1" stop-color="#b69a6d" stop-opacity=".15"/></linearGradient></defs><ellipse cx="300" cy="130" rx="124" ry="72" class="orbit outer"/><ellipse cx="300" cy="130" rx="95" ry="53" class="orbit inner"/><path id="incomeFlow" d="M65 55C150 55 175 130 280 130" class="flow-line"/><path id="purchaseFlow" d="M320 130C430 130 430 55 535 55" class="flow-line"/><path id="repairFlow" d="M320 130C430 130 430 210 535 210" class="flow-line"/><g v-if="motion" v-for="n in 4" :key="n"><circle r="3" fill="#e5d6ae"><animateMotion :dur="4+n*.25+'s'" :begin="-n+'s'" repeatCount="indefinite"><mpath href="#incomeFlow"/></animateMotion></circle><circle r="2.5" fill="#d8b384"><animateMotion :dur="5+n*.2+'s'" :begin="-n+'s'" repeatCount="indefinite"><mpath href="#purchaseFlow"/></animateMotion></circle><circle r="2.5" fill="#d4a692"><animateMotion :dur="5+n*.3+'s'" :begin="-n+'s'" repeatCount="indefinite"><mpath href="#repairFlow"/></animateMotion></circle></g><circle cx="300" cy="130" r="42" class="core-circle"/><text x="300" y="127" class="core-text">MES</text><text x="300" y="145" class="core-sub">经营核算</text><g class="node-label"><text x="65" y="37">销售收入</text><text x="535" y="37">采购支出</text><text x="535" y="235">维修支出</text></g><circle cx="65" cy="55" r="7" class="source-node"/><circle cx="535" cy="55" r="7" class="source-node"/><circle cx="535" cy="210" r="7" class="source-node"/></svg></div><div class="flow-bottom"><span><i/>{{overview.grossProfit<0?'期间支出高于收入':'期间收入覆盖支出'}}</span><small>粒子表示业务关联，不代表实时交易笔数</small></div></section>
<section class="screen-panel trend-panel"><div class="panel-particles" aria-hidden="true"><i v-for="n in 7" :key="n" :style="{left:(n*13)%100+'%',animationDelay:-n*.7+'s',animationDuration:5+n%3+'s'}"/></div><div class="panel-title"><h2>月度收支趋势</h2><small>按业务月份 · 元</small></div><div class="screen-legend"><span class="sage">● 销售</span><span class="gold">● 采购</span><span class="clay">● 维修</span><span>点击月份筛选</span></div><svg v-if="trend.length" viewBox="0 0 650 178" class="trend-chart" aria-label="真实月度收支柱状图"><g v-for="i in 4" :key="i"><path :d="`M60 ${140-(i-1)*40}H635`" class="grid-line"/><text x="53" :y="144-(i-1)*40" text-anchor="end">{{Math.round(max*(i-1)/3).toLocaleString()}}</text></g><g v-for="(r,i) in trend" :key="r.month" :transform="`translate(${x(i)} 0)`" class="chart-month" role="button" tabindex="0" :aria-label="'查看'+r.month+'收支'" @mouseenter="activeMonth=r.month" @focus="activeMonth=r.month" @click="emit('month',r.month)" @keydown.enter="emit('month',r.month)"><rect v-for="(v,j) in [r.salesIncome,r.purchaseExpense,r.maintenanceExpense]" :key="j" :x="j*Math.min(21,130/trend.length)" :y="140-height(v)" :width="Math.min(16,100/trend.length)" :height="height(v)" rx="2" :fill="['#8e9f83','#bb9764','#c29079'][j]"><title>{{r.month}} {{money(v)}}</title></rect><text x="17" y="163" text-anchor="middle">{{r.month}}</text></g></svg><div v-else class="empty">暂无月度业务记录</div><div v-if="hovered" class="trend-detail"><strong>{{hovered.month}}</strong><span>收入 {{money(hovered.salesIncome)}}</span><span>支出 {{money(Number(hovered.purchaseExpense)+Number(hovered.maintenanceExpense))}}</span></div></section></main>
<aside class="right-column"><section class="screen-panel expense-panel"><div class="panel-particles" aria-hidden="true"><i v-for="n in 7" :key="n" :style="{left:(n*13)%100+'%',animationDelay:-n*.7+'s',animationDuration:5+n%3+'s'}"/></div><div class="panel-title"><h2>支出结构分析</h2><small>{{scope}}</small></div><div class="ring-wrap"><div class="orbit-ring"/><div class="cost-ring" :style="{background:total?`conic-gradient(#b99767 ${share}%,#c59480 0)`:'#e8e0d4'}"><div><span>支出总额</span><strong>{{money(total)}}</strong></div></div></div><div class="cost-row"><span>● 采购支出</span><strong>{{share.toFixed(1)}}%</strong></div><div class="cost-row clay"><span>● 维修支出</span><strong>{{(total?100-share:0).toFixed(1)}}%</strong></div></section>
<section class="screen-panel material-panel"><div class="panel-particles" aria-hidden="true"><i v-for="n in 7" :key="n" :style="{left:(n*13)%100+'%',animationDelay:-n*.7+'s',animationDuration:5+n%3+'s'}"/></div><div class="panel-title"><h2>物料采购排行</h2><small>累计 TOP 5</small></div><div v-for="(r,i) in materials.slice(0,5)" :key="r.groupKey" class="screen-rank"><div><span><b>{{String(i+1).padStart(2,'0')}}</b>{{r.groupName}}</span><strong>{{money(r.amount)}}</strong></div><div class="rank-track"><i :style="{width:r.amount/Math.max(1,...materials.map(v=>v.amount))*100+'%'}"/></div></div><p v-if="!materials.length" class="empty">暂无物料采购记录</p></section></aside>
</div>
<div class="screen-bottom"><article><span>当前库存估值</span><strong>{{money(inventory.currentAmount)}}</strong><small>当前余额</small></article><article><span>低库存预警</span><strong>{{inventory.lowStockCount}}<em> 项</em></strong><small>关注补料计划</small></article><article><span>质检异常</span><strong>{{quality.defectiveQuantity}}<em> 件</em></strong><small>累计业务数量</small></article><article><span>报废 / 返工</span><strong>{{quality.scrapQuantity}}<em> / </em>{{quality.reworkQuantity}}</strong><small>累计处置数量</small></article></div>
<footer class="screen-footer"><span>收支差额不等同于会计利润 · 库存、排行与质量为当前 / 累计口径</span><nav><button v-for="e in entries" :key="e.path" @click="emit('navigate',e.path)">{{e.label}}<ArrowUpRight :size="11"/></button></nav></footer>
</section>
</template>
<style scoped>
